/**
 * Icon shapes. Most come from OpenAI's Apps SDK UI (MIT; see
 * `src/vendor/openai/`, regenerated by `scripts/sync-openai-design.mjs`):
 * solid shapes on a 24x24 grid, filled with currentColor. The four window
 * caption buttons keep hairline strokes of their own, because those are the
 * shapes Windows draws and people expect exactly them there.
 *
 * Data rather than markup so the set is testable without a DOM. `Icon.svelte`
 * is the only consumer and the only place that knows the two kinds apart:
 * callers ask for a name and get the same box either way.
 */
import { OPENAI_ICONS, type SolidIcon } from '../vendor/openai/icons';

export type StrokeIcon = { d: string };
export type IconDef = SolidIcon | StrokeIcon;

export function isSolid(def: IconDef): def is SolidIcon {
  return 'paths' in def;
}

export type IconName =
  | 'play' | 'pause' | 'clips' | 'settings' | 'star' | 'star-filled'
  | 'pencil' | 'trash' | 'folder' | 'scissors' | 'volume' | 'volume-low'
  | 'volume-mute'
  | 'fullscreen' | 'fullscreen-exit' | 'chevron-left' | 'chevron-right'
  | 'chevron-down' | 'dots' | 'check' | 'rearm' | 'minimize' | 'maximize'
  | 'restore' | 'close' | 'alert' | 'camera' | 'copy';

export const ICONS: Record<IconName, IconDef> = {
  ...OPENAI_ICONS,
  minimize: { d: 'M4.5 12h15' },
  maximize: { d: 'M5.25 5.25h13.5v13.5H5.25z' },
  restore: { d: 'M7.5 7.5V5.25h11.25V16.5H16.5M5.25 7.5H16.5v11.25H5.25z' },
  close: { d: 'M5.25 5.25l13.5 13.5M18.75 5.25l-13.5 13.5' },
};
